def transform_v3(grid):
    h, w = len(grid), len(grid[0])
    output = [[0]*4 for _ in range(4)]
    separator_col = 4

    for i in range(4):
        left_row = grid[i][:4]
        right_row = grid[i][separator_col+1:]

        # Count non-zeros
        left_nonzeros = sum(1 for x in left_row if x != 0)
        right_nonzeros = sum(1 for x in right_row if x != 0)

        if left_nonzeros == 0 and right_nonzeros == 0:
            # All zeros case: all 2s
            output[i] = [2, 2, 2, 2]
        else:
            for j in range(4):
                if left_row[j] != 0:
                    output[i][j] = 1
                else:
                    if right_row[j] == 0:
                        output[i][j] = 1
                    else:
                        output[i][j] = right_row[j]
    return output

